package com.example

import com.example.ExamQuestionHelper.QSpec

internal object BuddhismG11LiveExamPhilosophyBank2 {
  private const val T = "මූලික බෞද්ධ දර්ශනය"

  private fun q(
    stem: String,
    c: String,
    d1: String,
    d2: String,
    d3: String,
    exp: String
  ) = QSpec(T, stem, c, listOf(d1, d2, d3), exp)

  fun questions(): List<QSpec> = listOf(
    q("සියලු සංස්කාර ධර්මයන් සැමවිටම වෙනස් වන සුළු බව දැක්වෙන ත්‍රිලක්ෂණයේ පළමු ලක්ෂණය කුමක්ද?", "අනිත්‍ය", "දුක්ඛ", "අනාත්ම", "ශුන්‍ය", "'සබ්බේ සංඛාරා අනිච්චා' ලෙස සියලු සංස්කාර වෙනස් වන බව දේශනා කෙරේ."),
    q("සියලු සංස්කාර ධර්මයන් පීඩාකාරී ස්වභාවයෙන් යුතු බව දැක්වෙන ලක්ෂණය කුමක්ද?", "දුක්ඛ", "අනිත්‍ය", "අනාත්ම", "නිත්‍ය", "ඇති වී නැති වී යාම නිසා සංස්කාර ධර්මයෝ දුක්ඛ ස්වභාවයෙන් යුක්තය."),
    q("සියලු ධර්මයන් තමාගේ වසඟයේ පැවැත්විය නොහැකි බව දැක්වෙන ලක්ෂණය කුමක්ද?", "අනාත්ම", "අනිත්‍ය", "දුක්ඛ", "සංඛත", "'සබ්බේ ධම්මා අනත්තා' ලෙස නිර්වාණය ඇතුළු සියලු ධර්ම අනාත්ම බව දේශනා කෙරේ."),
    q("පංච උපාදානස්කන්ධය අයත් වන කොටස් පහ නිවැරදිව දැක්වෙන කාණ්ඩය තෝරන්න.", "රූප, වේදනා, සඤ්ඤා, සංඛාර, විඤ්ඤාණ", "පඨවි, ආපෝ, තේජෝ, වායෝ, ආකාස", "චක්ඛු, සෝත, ඝාණ, ජිව්හා, කාය", "දාන, සීල, භාවනා, ඛන්ති, මෙත්තා", "රූප හා නාම කොටස් 4ක් එක්වීමෙන් පංචස්කන්ධය සැදී ඇත."),
    q("පංචස්කන්ධයෙන් පඨවි, ආපෝ, තේජෝ, වායෝ යන සතර මහා භූතයන්ගෙන් සෑදුණු කොටස කුමක්ද?", "රූපස්කන්ධය", "වේදනාස්කන්ධය", "සඤ්ඤාස්කන්ධය", "විඤ්ඤාණස්කන්ධය", "භෞතික ශරීරය රූපස්කන්ධයට අයත් වේ."),
    q("සැප, දුක් හා උපේක්ෂා (අදුක්ඛමසුඛ) යන විඳීම් අයත් වන්නේ කුමන ස්කන්ධයටද?", "වේදනාස්කන්ධය", "සඤ්ඤාස්කන්ධය", "සංඛාරස්කන්ධය", "රූපස්කන්ධය", "ඉන්ද්‍රිය හරහා ලබන සියලු විඳීම් වේදනාස්කන්ධයයි."),
    q("වර්ණ, ශබ්ද ආදී අරමුණු හඳුනාගැනීමේ මානසික ක්‍රියාවලිය කුමන ස්කන්ධයද?", "සඤ්ඤාස්කන්ධය", "වේදනාස්කන්ධය", "සංඛාරස්කන්ධය", "විඤ්ඤාණස්කන්ධය", "නිල්, රතු ආදී වශයෙන් අරමුණු හඳුනා ගැනීම සඤ්ඤා නම් වේ."),
    q("චේතනාව ප්‍රමුඛ කොටගත් කුසලාකුසල චෛතසික රැස්වීම කුමන ස්කන්ධයට අයත්ද?", "සංඛාරස්කන්ධය", "විඤ්ඤාණස්කන්ධය", "වේදනාස්කන්ධය", "රූපස්කන්ධය", "වේදනා හා සඤ්ඤා හැර අනෙක් චෛතසික සංඛාරස්කන්ධයට අයත් වේ."),
    q("ඇස, කන ආදී ඉන්ද්‍රියන්ට අරමුණු හමුවූ විට දැනගැනීමේ ස්වභාවය කුමන ස්කන්ධයද?", "විඤ්ඤාණස්කන්ධය", "සඤ්ඤාස්කන්ධය", "සංඛාරස්කන්ධය", "රූපස්කන්ධය", "චක්ඛු විඤ්ඤාණ ආදී වශයෙන් අරමුණු දැනීම විඤ්ඤාණයයි."),
    q("පස්වග මහණුන් අරහත් ඵලයට පත් කිරීම සඳහා පංචස්කන්ධය අනාත්ම බව දෙසූ සූත්‍රය කුමක්ද?", "අනත්තලක්ඛණ සූත්‍රය", "ධම්මචක්කප්පවත්තන සූත්‍රය", "ආදිත්තපරියාය සූත්‍රය", "සතිපට්ඨාන සූත්‍රය", "පංචස්කන්ධය මමය, මාගේය, මාගේ ආත්මය නොවන බව මෙහිදී විස්තර කෙරේ."),
    q("අනත්තලක්ඛණ සූත්‍රයේදී 'පෙණ පිඬකට' උපමා කර ඇත්තේ කුමන ස්කන්ධයද?", "රූපස්කන්ධය", "වේදනාස්කන්ධය", "සඤ්ඤාස්කන්ධය", "විඤ්ඤාණස්කන්ධය", "රූපය පෙණ පිඬක් මෙන් නිසරු බව ඵේණපිණ්ඩූපම සූත්‍රයේදී වදාළහ."),
    q("පටිච්චසමුප්පාද ධර්මයේ මූලික රීතිය පාලියෙන් දැක්වෙන්නේ කෙසේද?", "ඉමස්මිං සති ඉදං හෝති", "සබ්බේ සංඛාරා අනිච්චා", "යේ ධම්මා හේතුප්පභවා", "චේතනාහං භික්ඛවේ කම්මං", "'මෙය ඇති කල්හි මෙය වේ' යන හේතුඵල සම්බන්ධතාව මෙයින් කියවේ."),
    q("ද්වාදශාංග පටිච්චසමුප්පාදයේ පළමු අංගය කුමක්ද?", "අවිද්‍යාව", "සංඛාර", "විඤ්ඤාණ", "තණ්හාව", "චතුරාර්ය සත්‍යය නොදැනීම හෙවත් අවිද්‍යාව මුල්ම අංගයයි."),
    q("'අවිද්‍යා පච්චයා සංඛාරා' යන්නට අනුව සංඛාර ප්‍රත්‍යයෙන් හටගන්නේ කුමක්ද?", "විඤ්ඤාණය", "නාමරූප", "සළායතන", "ඵස්ස", "කර්ම සංස්කාර හේතුවෙන් ප්‍රතිසන්ධි විඤ්ඤාණය හටගනී."),
    q("පටිච්චසමුප්පාදයේ 'විඤ්ඤාණ පච්චයා' යනුවෙන් අනතුරුව හටගන්නේ කුමක්ද?", "නාමරූප", "සළායතන", "වේදනා", "උපාදාන", "විඤ්ඤාණය හේතුවෙන් නාමරූප පහළ වේ."),
    q("පටිච්චසමුප්පාදයේ 'නාමරූප පච්චයා' යන්නෙන් හටගන්නේ කුමක්ද?", "සළායතන", "ඵස්ස", "තණ්හා", "භව", "නාමරූප හේතුවෙන් ආයතන සය (සළායතන) හටගනී."),
    q("පටිච්චසමුප්පාද චක්‍රයේ සළායතන හේතුවෙන් ඇතිවන්නේ කුමක්ද?", "ඵස්සය (ස්පර්ශය)", "වේදනාව", "තණ්හාව", "ජාතිය", "ඉන්ද්‍රිය හා අරමුණු ගැටීම හෙවත් ඵස්සය සළායතන නිසා ඇතිවේ."),
    q("පටිච්චසමුප්පාදයේ වේදනාව හේතුවෙන් හටගන්නේ කුමක්ද?", "තණ්හාව", "උපාදානය", "භවය", "ජරා මරණ", "විඳීම නිසා ඇතිවන ඇල්ම හෙවත් තණ්හාව සසර දිගු කරයි."),
    q("'තණ්හා පච්චයා උපාදානං' යන්නෙහි 'උපාදාන' යන්නෙන් අදහස් කරන්නේ කුමක්ද?", "දැඩිව අල්ලා ගැනීම", "හැර දැමීම", "විමසා බැලීම", "සංසිඳීම", "කාම, දිට්ඨි, සීලබ්බත, අත්තවාද යන සතර උපාදාන මෙයට අයත් වේ."),
    q("උපාදාන හේතුවෙන් හටගෙන ජාතියට හේතු වන පටිච්චසමුප්පාද අංගය කුමක්ද?", "භවය", "සංඛාර", "විඤ්ඤාණ", "නාමරූප", "උපාදාන පච්චයා භවෝ, භව පච්චයා ජාති යනුවෙන් දැක්වේ."),
    q("පටිච්චසමුප්පාද චක්‍රයේ අවසාන අංගය ලෙස දැක්වෙන්නේ කුමක්ද?", "ජරා මරණ", "ජාති", "භව", "වේදනා", "ඉපදීම නිසා ජරා, මරණ, ශෝක, පරිදේව ආදිය හටගනී."),
    q("සතර ආහාර අතරින් සත්වයාගේ පැවැත්මට උපකාරී වන 'කබලිංකාර ආහාරය' යනු කුමක්ද?", "ශරීරය පෝෂණය කරන භෞතික ආහාරය", "සිතුවිලි ආහාරය", "ස්පර්ශ ආහාරය", "විඤ්ඤාණ ආහාරය", "කබලිංකාර, ඵස්ස, මනෝසංචේතනා, විඤ්ඤාණ යනු සතර ආහාරයි."),
    q("ද්වාදශාංග පටිච්චසමුප්පාදයේ ඇතුළත් මුළු අංග සංඛ්‍යාව කීයද?", "අංග 12 කි", "අංග 8 කි", "අංග 10 කි", "අංග 16 කි", "අවිද්‍යාවේ සිට ජරා මරණ දක්වා අංග 12 කි."),
    q("පංචස්කන්ධයේ 'වේදනා, සඤ්ඤා, සංඛාර, විඤ්ඤාණ' යන සතර කොටස පොදුවේ හඳුන්වන්නේ කෙසේද?", "නාම ධර්ම", "රූප ධර්ම", "භූත ධර්ම", "අසංඛත ධර්ම", "සිත හා චෛතසික නාම කොටසට අයත් වේ."),
    q("සතර මහා භූතයන් අතරින් තද ගතිය හා බර බව ප්‍රකට කරන ධාතුව කුමක්ද?", "පඨවි ධාතුව", "ආපෝ ධාතුව", "තේජෝ ධාතුව", "වායෝ ධාතුව", "තද හා මෘදු ස්වභාවය පඨවි ධාතුවේ ලක්ෂණයයි."),
    q("සතර මහා භූතයන්ගෙන් බැඳීම් ස්වභාවය හා වැගිරීම ප්‍රකට කරන ධාතුව කුමක්ද?", "ආපෝ ධාතුව", "පඨවි ධාතුව", "තේජෝ ධාතුව", "වායෝ ධාතුව", "රුධිරය, ඛේටය, ජලය ආදියෙහි ආපෝ ධාතුව අධික වේ."),
    q("ශරීරයේ උණුසුම හා ආහාර දිරවීමට උපකාරී වන මහා භූත ධාතුව කුමක්ද?", "තේජෝ ධාතුව", "වායෝ ධාතුව", "පඨවි ධාතුව", "ආපෝ ධාතුව", "උණුසුම හා සිසිලස තේජෝ ධාතුවේ ලක්ෂණයයි."),
    q("චලනය හා ආශ්වාස ප්‍රශ්වාස ක්‍රියාවලිය සිදු කරන මහා භූත ධාතුව කුමක්ද?", "වායෝ ධාතුව", "තේජෝ ධාතුව", "ආපෝ ධාතුව", "පඨවි ධාතුව", "සැලීම හා පැතිරීම වායෝ ධාතුවේ ස්වභාවයයි."),
    q("බෞද්ධ දර්ශනයට අනුව සළායතන යටතේ ගැනෙන ආධ්‍යාත්මික ආයතන හයෙන් එකක් නොවන්නේ කුමක්ද?", "රූපායතනය", "චක්ඛායතනය", "සෝතායතනය", "මනායතනය", "රූපය බාහිර ආයතනයක් වන අතර ඇස, කන, නාසය, දිව, කය, මනස ආධ්‍යාත්මික ආයතන වේ."),
    q("ධම්මසංගණී, විභංග ආදී අභිධර්ම පිටකයේ විග්‍රහ වන පරමාර්ථ ධර්ම සතර මොනවාද?", "චිත්ත, චෛතසික, රූප, නිබ්බාන", "දුක්ඛ, සමුදය, නිරෝධ, මාර්ග", "අනිච්ච, දුක්ඛ, අනත්ත, සුඤ්ඤත", "පඨවි, ආපෝ, තේජෝ, වායෝ", "අභිධර්මයේ මූලික ඉගැන්වීම මෙම පරමාර්ථ ධර්ම සතර මත පදනම් වේ."),
    q("චිත්ත චෛතසික ධර්ම ඇසුරින් සිත සමඟම උපදින මානසික සාධක හඳුන්වන්නේ කුමන නමකින්ද?", "චෛතසික", "රූප කලාප", "පංචේන්ද්‍රිය", "ධ්‍යානාංග", "චෛතසික 52ක් අභිධර්මයේ විස්තර කෙරේ."),
    q("සෑම සිතකම අනිවාර්යයෙන් යෙදෙන චෛතසික හත හඳුන්වන්නේ කෙසේද?", "සබ්බචිත්තසාධාරණ චෛතසික", "පකිණ්ණක චෛතසික", "අකුසල සාධාරණ චෛතසික", "සෝභන සාධාරණ චෛතසික", "ඵස්ස, වේදනා, සඤ්ඤා, චේතනා, ඒකග්ගතා, ජීවිතින්ද්‍රිය, මනසිකාර සබ්බචිත්තසාධාරණ වේ."),
    q("අනිත්‍ය, දුක්ඛ, අනාත්ම යන ත්‍රිලක්ෂණය පිළිබඳ නුවණ ලබා ගන්නේ කුමන භාවනාවෙන්ද?", "විදර්ශනා භාවනාව", "සමථ භාවනාව", "කසිණ භාවනාව", "ආරක්ෂක භාවනාව", "සමථයෙන් සිත එකඟ කර විදර්ශනාවෙන් ත්‍රිලක්ෂණය අවබෝධ කර ගනී."),
    q("බෞද්ධ සමාජ දර්ශනය තුළ සියලු සත්වයන් සමාන වන්නේ කුමන කරුණක් මතද?", "චතුරාර්ය සත්‍යය අවබෝධ කිරීමේ හැකියාව මත", "ධනවත් බව මත", "උපන් කුලය මත", "ශරීර වර්ණය මත", "සෑම මිනිසෙකුටම උත්සාහයෙන් විමුක්තිය ලැබීමේ සමාන අවස්ථාව ඇත."),
    q("බුදුදහම 'විභජ්ජවාදයක්' ලෙස හඳුන්වන්නේ ඇයි?", "කරුණු බෙදා විශ්ලේෂණය කර පෙන්වා දෙන බැවින්", "එකම පිළිතුරක් බලෙන් පටවන බැවින්", "කිසිවක් ප්‍රශ්න නොකරන බැවින්", "මිථ්‍යා විශ්වාස අනුගමනය කරන බැවින්", "සෑම ගැටලුවක්ම විවිධ පැතිවලින් විශ්ලේෂණය කර පෙන්වීම බුදුරදුන්ගේ ක්‍රමයයි."),
    q("මිලින්ද ප්‍රශ්නයේදී නාගසේන හිමියන් 'පුද්ගලයා තුළ ආත්මයක් නැති බව' පෙන්වීමට දුන් උපමාව කුමක්ද?", "රථය පිළිබඳ උපමාව", "වීණාව පිළිබඳ උපමාව", "නෙළුම් මලේ උපමාව", "දිය ඇල්ලේ උපමාව", "රෝද, අක්ෂය ආදී කොටස් හැර වෙනම රථයක් නැති සේම ස්කන්ධ හැර ආත්මයක් නැත."),
    q("පුනර්භවයේදී එකම පුද්ගලයාද නැතහොත් වෙනස් පුද්ගලයෙකුද උපදින්නේ යන ප්‍රශ්නයට බෞද්ධ පිළිතුර කුමක්ද?", "න ච සෝ න ච අඤ්ඤෝ (එයාමත් නොවේ වෙන අයෙකුත් නොවේ)", "එම පුද්ගලයාම සදාකාලිකව උපදී", "සම්පූර්ණයෙන්ම වෙනස් අයෙකි", "කිසිදු සම්බන්ධයක් නැත", "නාමරූප පරම්පරාවේ සන්තතික භාවය මෙයින් පැහැදිලි වේ."),
    q("සත්වයාගේ කෙලෙස් අවුස්සන ප්‍රධාන ආස්‍රව (ආසව) ධර්ම සතරෙන් එකක් නොවන්නේ කුමක්ද?", "ප්‍රඥාසව", "කාමාසව", "භවාසව", "අවිජ්ජාසව", "කාම, භව, දිට්ඨි හා අවිජ්ජා යනු සතර ආස්‍රවයන්ය."),
    q("සංසාරයේ සත්වයා බැඳ තබන 'ඕඝ' හතර අතරට අයත් නොවන්නේ කුමක්ද?", "මෛත්‍රී ඕඝය", "කාම ඕඝය", "භව ඕඝය", "අවිජ්ජා ඕඝය", "කාම, භව, දිට්ඨි, අවිජ්ජා යනු චතුරෝඝයයි."),
    q("සත්වයාට දුක ගෙන දෙන තෘෂ්ණාව උපදින්නේ කුමන ඉන්ද්‍රිය හා අරමුණු සම්බන්ධයෙන්ද?", "ආයතන සය හා ඒවායේ අරමුණු මුල්කරගෙන", "අවිද්‍යාවෙන් පමණක්", "කායික වේදනාවෙන් පමණක්", "වැරදි ආහාර නිසා", "ප්‍රිය රූප ආදී අරමුණුවල ඇලීමෙන් තණ්හාව උපදී."),
    q("ත්‍රිවිධ සංඛාර අතරින් පුණ්‍ය කර්මවලට අදාළ සංස්කාර හඳුන්වන්නේ කුමන නමකින්ද?", "පුඤ්ඤාභිසංඛාර", "අපුඤ්ඤාභිසංඛාර", "ආනෙඤ්ජාභිසංඛාර", "කාය සංඛාර", "කාමාවචර කුසල හා රූපාවචර කුසල පුඤ්ඤාභිසංඛාර නම් වේ."),
    q("අරූපාවචර කුසල චේතනා හඳුන්වන්නේ කුමන සංඛාර කොටස ලෙසද?", "ආනෙඤ්ජාභිසංඛාර", "පුඤ්ඤාභිසංඛාර", "අපුඤ්ඤාභිසංඛාර", "වචී සංඛාර", "නොසැලෙන අරූප ධ්‍යාන කුසල් ආනෙඤ්ජාභිසංඛාර වේ."),
    q("රූපස්කන්ධයේ පවතින කුඩාම ඒකකය අභිධර්මයේ හඳුන්වන්නේ කෙසේද?", "රූප කලාප", "පරමාණු", "අණු", "චිත්ත ක්ෂණ", "ශුද්ධාෂ්ටක ආදී රූප කලාප ඉතා වේගයෙන් ඇති වී නැති වේ."),
    q("ප්‍රථම ධ්‍යානයට අයත් ධ්‍යානාංග පහ මොනවාද?", "විතක්ක, විචාර, පීති, සුඛ, ඒකග්ගතා", "මෙත්තා, කරුණා, මුදිතා, උපේක්ඛා, සති", "සද්ධා, විරිය, සති, සමාධි, පඤ්ඤා", "රූප, වේදනා, සඤ්ඤා, සංඛාර, විඤ්ඤාණ", "ධ්‍යානාංග පහෙන් පංච නීවරණ යටපත් කොට ප්‍රථම ධ්‍යානය ලබයි."),
    q("ද්විතීය ධ්‍යානයේදී ප්‍රහාණය වන ධ්‍යානාංග දෙක මොනවාද?", "විතක්ක හා විචාර", "පීති හා සුඛ", "සුඛ හා ඒකග්ගතා", "විතක්ක හා පීති", "සිත ගැඹුරු වත්ම විතර්ක හා විචාර සංසිඳේ."),
    q("සිව්වන ධ්‍යානයේදී සුඛය වෙනුවට පවතින උසස් මානසික තත්ත්වය කුමක්ද?", "උපේක්ෂා හා ඒකග්ගතා", "ප්‍රීතිය හා විතර්කය", "විචාරය හා සුඛය", "කාමච්ඡන්දය", "සැප දුක් දෙකෙන්ම මිදුණු උපේක්ෂා ඒකග්ගතාව චතුර්ථ ධ්‍යානයයි."),
    q("සත්වයාගේ ප්‍රතිසන්ධිය ලැබීමට අත්‍යවශ්‍ය මරණාසන්න චිත්ත වීථියේ අවසාන සිත කුමක්ද?", "චුති සිත", "ප්‍රතිසන්ධි සිත", "භවාංග සිත", "ජවන් සිත", "එක් භවයක අවසන් සිත චුති සිත වන අතර ඊළඟ භවයේ මුල් සිත ප්‍රතිසන්ධි සිතයි."),
    q("භාවනාමය ප්‍රඥාවට අමතරව ප්‍රඥාව වර්ධනය වන අනෙක් ආකාර දෙක මොනවාද?", "සුතමය හා චින්තාමය ප්‍රඥාව", "දානමය හා ශීලමය", "ලෞකික හා ආගමික", "සමථ හා ධ්‍යාන", "ඇසීමෙන් (සුතමය), සිතීමෙන් (චින්තාමය) හා භාවනාවෙන් (භාවනාමය) ප්‍රඥාව වැඩේ."),
    q("ලෝකයේ ස්වභාවික යථාර්ථය නොදැනීම නිසා ඇතිවන මුළාව බුදුදහමේ හඳුන්වන්නේ කුමන නමින්ද?", "අවිද්‍යාව (මෝහය)", "වීර්යය", "ප්‍රඥාව", "ශ්‍රද්ධාව", "චතුරාර්ය සත්‍යය ආවරණය කරන මූලික කෙලෙසය අවිද්‍යාවයි."),
    q("අන් අයගේ සම්පත් හා දියුණුව දැක සිතේ ඇතිවන නොසතුට හා ද්වේෂය කුමක්ද?", "ඊර්ෂ්‍යාව (ඉස්සා)", "මසුරුකම (මච්ඡරිය)", "මුදිතාව", "උපේක්ෂාව", "මුදිතා ගුණය වැඩීමෙන් ඊර්ෂ්‍යාව දුරු කළ හැකිය."),
    q("තමා සතු දේ අන් අයට දීමට ඇති අකමැත්ත හඳුන්වන අකුසල චෛතසිකය කුමක්ද?", "මච්ඡරිය (මසුරුකම)", "දානය", "මෛත්‍රිය", "කරුණාව", "ත්‍යාගශීලී බව පුරුදු කිරීමෙන් මසුරුකම නැති වේ."),
    q("බුදුරදුන් 'ධම්මෝ හවේ රක්ඛති ධම්මචාරී' යනුවෙන් දේශනා කළේ කුමක්ද?", "ධර්මයේ හැසිරෙන්නා ධර්මය විසින්ම රකින බව", "ධනය මිනිසා රකින බව", "බලයෙන් සතුට ලැබෙන බව", "දෙවියන් මිනිසුන් රකින බව", "ධාර්මික ජීවිතය මෙලොව පරලොව දෙකේම ආරක්ෂාව සලසයි."),
    q("පංච උපාදානස්කන්ධයෙන් පිටස්තරව පවතින සදාකාලික 'මම' කෙනෙකු නොමැති බව දැක්වෙන දහම කුමක්ද?", "අනාත්මවාදය", "ආත්මවාදය", "භෞතිකවාදය", "සර්වේශ්වරවාදය", "බුදුදහම අනෙක් දර්ශනවලින් වෙනස් වන ප්‍රධාන ලක්ෂණය අනාත්ම දර්ශනයයි."),
    q("සියලු ධර්මයන්ගේ අනිත්‍ය ස්වභාවය නිසා ඒවා අල්ලා ගැනීමෙන් ඇතිවන්නේ කුමක්ද?", "දුක හා බිය", "සදාකාලික සතුට", "නිර්වාණය", "අමරණීය බව", "වෙනස් වන දේ නිත්‍ය ලෙස ගැනීම සියලු මානසික දුක්වලට හේතුවයි."),
    q("නිවැරදිව ප්‍රඥාව වඩා කෙලෙස් නැසීමේදී පුද්ගලයා තුළ පළමුවෙන්ම ඇතිවන උසස් ඤාණය කුමක්ද?", "නාමරූප පරිච්ඡේද ඤාණය", "ආසවක්ඛය ඤාණය", "චුතූපපාත ඤාණය", "ඉද්ධිවිධ ඤාණය", "නාම හා රූප වෙන්කර හඳුනාගැනීම විදර්ශනාවේ මුල් පියවරයි."),
    q("ප්‍රතිසන්ධිය ලැබීමේදී ශරීරයෙන් වෙන්වී ඊළඟ භවයට යන සදාකාලික ප්‍රාණයක් හෝ ආත්මයක් නැති බව දැක්වූයේ කවුද?", "සාති භික්ෂුවට බුදුරදුන්", "උපාලි හිමිට", "ආනන්ද හිමිට", "සුනීත හිමිට", "මහාතණ්හාසංඛය සූත්‍රයේදී විඤ්ඤාණය හේතුඵල අනුව උපදින බව පෙන්වූහ."),
    q("සසර ගමන නවතා නිවන් අවබෝධ කිරීමට අවශ්‍ය බෝධිපාක්ෂික ධර්ම සමස්ත සංඛ්‍යාව කීයද?", "තිස් හතකි (37)", "විසි හතරකි", "දොළොසකි", "හතළිස් දෙකකි", "සතර සතිපට්ඨාන, සතර සම්‍යක් ප්‍රධාන, සතර ඉර්දිපාද, පංච ඉන්ද්‍රිය, පංච බල, සප්ත බොජ්ඣංග, ආර්ය අෂ්ටාංගික මාර්ගය 37 කි."),
    q("බෝධිපාක්ෂික ධර්ම අතරට අයත් 'සතර ඉර්දිපාද' මොනවාද?", "ඡන්ද, චිත්ත, විරිය, වීමංසා", "දාන, සීල, භාවනා, පඤ්ඤා", "මෙත්තා, කරුණා, මුදිතා, උපේක්ඛා", "සද්ධා, සති, සමාධි, පඤ්ඤා", "ඕනෑම උතුම් අරමුණක් ජය ගැනීමට කැමැත්ත, සිත, වීර්යය හා විමසීම ඉර්දිපාද වේ."),
    q("රූප, ශබ්ද, ගන්ධ, රස, ස්පර්ශ යන පංච කාමයන් නිසා සිතේ ඇතිවන රාගය හැඳින්වෙන්නේ කෙසේද?", "කාමච්ඡන්දය", "ව්‍යාපාදය", "ථීනමිද්ධය", "විචිකිච්ඡාව", "පංච නීවරණවල පළමු නීවරණය කාමච්ඡන්දයයි."),
    q("බෞද්ධ සදාචාරයේ හා දර්ශනයේ 'අවිහිංසාව' යන්නෙන් අදහස් වන්නේ කුමක්ද?", "සියලු සතුන්ට හිංසා නොකිරීම හා කරුණාව දැක්වීම", "තමන්ට පමණක් ආදරය කිරීම", "සතුරන්ට පහර දීම", "නිහඬව සිටීම පමණක්", "කයින්, වචනයෙන් හා සිතින් හිංසාවෙන් වැළකීම අවිහිංසාවයි."),
    q("මරණින් පසු දුගතියක නොඉපිද සුගතියේ හෝ නිවන් මඟේ ස්ථාවර වීමට ඇති ප්‍රධානම සරණ කුමක්ද?", "තිසරණ සරණ", "දේව සරණ", "නැකැත් සරණ", "ධන සරණ", "බුද්ධ, ධම්ම, සංඝ යන ත්‍රිවිධ රත්නය සරණ යාම ලෝකෝත්තර සරණයට මඟ පාදයි."),
    q("බුදුදහමට අනුව 'සැබෑ වීරයා' යනු කවුද?", "තම සිතේ කෙලෙස් සතුරන් පරාජය කළ තැනැත්තා", "යුද පිටියේ දහස් ගණනක් පරදවන්නා", "විශාල ධනයක් උපයන්නා", "කායික ශක්තිය වැඩිම තැනැත්තා", "ධම්මපදයේ 'යෝ සභස්සං සහස්සේන...' ගාථාවෙන් ආත්ම ජයග්‍රහණය අගය කරයි."),
    q("ගිහිගෙය අතහැර නොගොස් වුවද කෙලෙස් තුනී කොට ලබාගත හැකි ඉහළම ආර්ය ඵලය කුමක්ද?", "අනාගාමී ඵලය", "පසේබුදු බව", "මහා බ්‍රහ්ම පදවිය", "සක්විති රජකම", "අනාගාමී වන තෙක් ගිහි වතින්ම මාර්ග ඵල ලැබූ උපාසක උපාසිකාවෝ බොහෝ වූහ."),
    q("බුදුදහමේ 'අප්පමාදය' යනුවෙන් අදහස් කරන්නේ කුමක්ද?", "සිහියෙන් හා උත්සාහයෙන් කුසලයේ නිරත වීම", "කම්මැලිකමින් කාලය ගෙවීම", "කලබලයෙන් වැඩ කිරීම", "පමා වී කටයුතු කිරීම", "'සති අවිප්පවාසෝ' හෙවත් සිහියෙන් තොර නොවීම අප්‍රමාදයයි."),
    q("කෙනෙකුගේ ජීවිතයේ සැබෑ වටිනාකම තීරණය වන්නේ කුමක් මත බව බුදුදහම උගන්වයිද?", "සදාචාරාත්මක චරිතය හා ක්‍රියාව මත", "උපන් ජාතිය හා කුලය මත", "පවුලේ වස්තුව මත", "බාහිර රූප සොබාව මත", "'කම්මුනා වසලෝ හෝති - කම්මුනා හෝති බ්‍රාහ්මණෝ' යනුවෙන් වදාළහ."),
    q("නිර්වාණය පිළිබඳව සඳහන් කිරීමේදී 'නිබ්බානං පරමං සුඛං' යන්නෙහි අර්ථය කුමක්ද?", "නිවන පරම සැපය වේ", "ධනය පරම සැපය වේ", "සෞඛ්‍යය පරම සැපය වේ", "දෙව්ලොව පරම සැපය වේ", "සියලු තෘෂ්ණා දාහයන් නිවී යාමෙන් ලබන නිවන පරම සුවයයි."),
    q("සංස්කාරයන්ගේ නැසෙන සුළු බව නිසා ඇතිවන බුද්ධිමත් කළකිරීම හඳුන්වන්නේ කෙසේද?", "නිබ්බිදාව (විදර්ශනා කළකිරීම)", "ද්වේෂය", "ශෝකය", "භය", "ලෝක ස්වභාවය යථාර්ථයෙන් දැක ඇලීමෙන් වෙන්වීම නිබ්බිදාවයි."),
    q("සත්වයා කෙලෙස් බැමිවලින් මිදී ලබන විමුක්තිය සඳහා අත්‍යවශ්‍ය ගුණාංග තුන මොනවාද?", "අලෝභ, අදෝස, අමෝහ", "ලෝභ, දෝස, මෝහ", "ඡන්ද, දෝස, භය", "කාම, භව, විභව", "ත්‍රිවිධ කුසල මූල නිවන් මඟට පදනම සපයයි."),
    q("බෞද්ධ දර්ශනයේ 'ප්‍රඥාව' මගින් සිදු කරන ප්‍රධානම කාර්යය කුමක්ද?", "මෝහය හෙවත් අවිද්‍යාව දුරු කිරීම", "කායික වේදනා වැඩි කිරීම", "මසුරුකම වැඩි කිරීම", "බිය ඇති කිරීම", "ආලෝකයක් මෙන් අවිද්‍යා අන්ධකාරය නැසීම ප්‍රඥාවේ ලක්ෂණයයි."),
    q("සම්මා දිට්ඨිය ඇති කර ගැනීමට උපකාරී වන බාහිර හා අභ්‍යන්තර ප්‍රත්‍යය දෙක මොනවාද?", "පරතෝඝෝෂය හා යෝනිසෝ මනසිකාරය", "ධනය හා බලය", "උපත හා කුලය", "නැකැත් හා පූජා", "කල්‍යාණ මිත්‍රයන්ගෙන් දහම් ඇසීම හා නුවණින් මෙනෙහි කිරීම සම්මා දිට්ඨිය ඇති කරයි."),
    q("නුවණින් විමසා බලා කරුණු සිතීම බුදුදහමේ හඳුන්වන විශේෂ වචනය කුමක්ද?", "යෝනිසෝ මනසිකාරය", "අයෝනිසෝ මනසිකාරය", "පරතෝඝෝෂය", "මිථ්‍යා සංකල්පය", "හේතුඵල අනුව නුවණින් මෙනෙහි කිරීම යෝනිසෝ මනසිකාරයයි."),
    q("තමන් තුළ ඇතිවන රාග, ද්වේෂ, මෝහ යටපත් නොකර නුසුදුසු ලෙස සිතීම කුමක්ද?", "අයෝනිසෝ මනසිකාරය", "යෝනිසෝ මනසිකාරය", "සම්මා සංකප්ප", "සම්මා සති", "අයෝනිසෝ මනසිකාරය නිසා අකුසල් හා නීවරණ ධර්ම වර්ධනය වේ."),
    q("බුදුරදුන් දෙසූ 'සබ්බේ සංඛාරා දුක්ඛා' යන ගාථාවේ තේරුම කුමක්ද?", "සියලු සංස්කාර ධර්මයෝ දුක් වෙති", "සියලු සංස්කාර සැප වෙති", "සියලු ධර්ම ආත්ම වෙති", "සියලු සංස්කාර නිත්‍ය වෙති", "අනිත්‍ය බව නිසාම සංස්කාරයෝ දුක්ඛ ස්වභාවය ගනිති."),
    q("ධර්මය නිවැරදිව පිළිපැදීම නිසා පරලොව සුගතිගාමී වීම හඳුන්වන්නේ කුමන සම්පත්තිය ලෙසද?", "සුගති සම්පත්තිය", "නිර්වාණ සම්පත්තිය", "භෝග සම්පත්තිය", "පිරිවර සම්පත්තිය", "සීලයෙන් හා දානයෙන් සුගති සම්පත්තිය ලැබේ."),
    q("කුසල් වැඩීමට ඇති හොඳම අවස්ථාව ලෙස බුදුදහමේ අගය කරන්නේ කුමන භවයද?", "මනුෂ්‍ය භවය", "තිරිසන් භවය", "අසුර භවය", "ප්‍රේත භවය", "සැප දුක් මිශ්‍රව ඇති මනුෂ්‍ය ලෝකය කුසල් වැඩීමට හා බුදු වීමට උචිතම තැනයි."),
    q("ලෝකයේ සිටින සියලු සත්වයන්ගේ සැප පැතීම දැක්වෙන පාලි පාඨය කුමක්ද?", "සබ්බේ සත්තා භවන්තු සුඛිතත්තා", "අත්තා හි අත්තනෝ නාථෝ", "නත්ථි සන්ති පරං සුඛං", "චරථ භික්ඛවේ චාරිකං", "කරණීයමෙත්ත සූත්‍රයේ එන මෛත්‍රී පැතුම මෙයයි."),
    q("ප්‍රඥාවන්ත පුද්ගලයා ලෝකයේ පවතින භෞතික දේවල නොඇලී ක්‍රියා කරන්නේ කෙසේද?", "නෙළුම් කොළයේ දිය බිඳුව මෙන්", "ගින්නේ පිදුරු මෙන්", "වතුරේ ලුණු මෙන්", "කිරි හා පැණි මෙන්", "ලෝකයේ ජීවත් වුවත් කෙලෙස්වලින් නොතැවරී සිටිය යුතු බව මෙයින් දැක්වේ."),
    q("සියලු ආර්ය සත්‍යයන් අවබෝධ කළ පසු බුදුරදුන්ට ඇතිවූ පරම නිෂ්ටාව කුමක්ද?", "අනුත්තර සම්මා සම්බෝධිය", "සක්විති රජ පදවිය", "සක් දෙව් පදවිය", "මාර පදවිය", "සියලු ඤෙය්‍ය ධර්ම අවබෝධ කිරීම සම්මා සම්බෝධියයි.")
  )
}
